const db = admin.firestore();
const { uid } = $json;

if (!uid) {
  return [{ json: { success: false, message: '❌ Missing user ID' } }];
}

const userRef = db.collection('users').doc(uid);
const userSnap = await userRef.get();

if (!userSnap.exists) {
  return [{ json: { success: false, message: '❌ User not found' } }];
}

const userData = userSnap.data();
const now = new Date();
const lastShared = userData.adSharedAt?.toDate?.() || new Date(0);
const diffHours = (now - lastShared) / (1000 * 60 * 60);

if (diffHours < 12) {
  return [{ json: { success: false, message: '❌ Already claimed within 12h' } }];
}

await userRef.update({
  adSharedAt: admin.firestore.Timestamp.fromDate(now),
  balance: admin.firestore.FieldValue.increment(50),
});

return [{ json: { success: true, message: '✅ 50 FSN rewarded for tweet share!' } }];
